{"file_text": "@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="success-message">
        <h2>✅ Recipe submitted!</h2>
        <p>Your recipe "<strong>@submission.Title</strong>" has been added.</p>
        <a href="/">Browse recipes</a>
    </div>
}
else
{
    <EditForm Model="submission" OnValidSubmit="HandleSubmit" class="recipe-form">
        <DataAnnotationsValidator />

        <div class="form-group">
            <label for="title">Title</label>
            <InputText id="title" @bind-Value="submission.Title" placeholder="e.g. Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="submission.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Thai">Thai</option>
                <option value="Mexican">Mexican</option>
                <option value="American">American</option>
                <option value="French">French</option>
                <option value="Japanese">Japanese</option>
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (comma-separated)</label>
            <InputTextArea id="ingredients" @bind-Value="submission.Ingredients"
                           placeholder="e.g. Flour, Sugar, Butter, Apples" rows="3" />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="submission.Steps"
                           placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. ..." rows="5" />
        </div>

        <button type="submit" class="submit-btn"
                disabled="@(string.IsNullOrWhiteSpace(submission.Title) || string.IsNullOrWhiteSpace(submission.Category))">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(submission.Title) || string.IsNullOrWhiteSpace(submission.Category))
            return;

        RecipeService.SubmitRecipe(submission);
        submitted = true;
    }
}
", "path": "/tmp/sv-19058e152e6e44b7b0745087dc603ef8/RecipeCommunity/Components/Pages/SubmitRecipe.razor"}

