+    <div class="stars">
+        @for (int i = 1; i <= 5; i++)
+        {
+            var star = i;
+            <button class="star-btn @(star <= selectedRating ? "selected" : "")"
+                    @onclick="() => SubmitRating(star)">
+                ★
+            </button>
